121	    /// What the scope menu offers: All, This Mac, Cloud, each cloud account, then each indexed drive.
122	    @Published var scopes: [SearchScope] = [.all]
123	    @Published var scope = SearchScope.all {
124	        didSet {
125	            // A fallback while a saved drive is unplugged must not forget that choice.
126	            if !restoring { UserDefaults.standard.set(scope.id, forKey: SearchModel.scopeKey) }
127	            run()
128	        }
