                tokens.append(.open(negated: !current.isEmpty))
                current = ""
                depth += 1
                continue
            }
            if ch == ">" && depth > 0 && !current.hasSuffix(":") && !inRegex() {
                flush()
                tokens.append(.close)
                depth -= 1
                continue
            }
            current.append(ch)
        }
        flush()
        return tokens
    }

